import { sql } from 'drizzle-orm';
import { check, integer, sqliteTable, text } from 'drizzle-orm/sqlite-core';

export const coordinator = sqliteTable(
  'coordinator',
  {
    singleton: integer().primaryKey(),
    pid: integer().notNull(),
    token: text().notNull(),
    port: integer(),
  },
  (table) => [check('coordinator_singleton', sql`${table.singleton} = 1`)],
);
